import { Group } from '@visx/group';
import { Pie } from '@visx/shape';
import { arc, DefaultArcObject } from 'd3-shape';
import React, { forwardRef, useMemo } from 'react';

import { container } from './PieChartPlot.sty.js';
import { useGraphSize } from '../../../core/components/chart-layout/hooks/useGraphSize.js';
import { buildChartSizes } from '../../functions/build-chart-sizes.js';
import { usePlotHandlers } from '../../hooks/usePlotHandlers.js';
import { InternalSliceData } from '../../types/internal/pie-chart.js';
import { PieChartProps } from '../../types/pie-chart.config.js';
import { InnerWrapper } from '../inner/InnerWrapper.js';
import { PieChartSlice } from '../PieChartSlice.js';

type PieChartPlotProps = Omit<PieChartProps, 'data'> & {
  variant: 'donut' | 'pie';
  data: InternalSliceData[];
};

const getValue = (pieData: InternalSliceData) => pieData.relativeValue;

export const PieChartPlot = forwardRef<HTMLDivElement, PieChartPlotProps>(
  (props, forwardedRef) => {
    const { variant, data } = props;
    const { height, width } = useGraphSize();
    const { onMouseEnterHandler, onMouseLeaveHandler, onMouseMoveHandler } =
      usePlotHandlers();
    const { topCenter, radius, leftCenter, innerRadius } = buildChartSizes(
      height,
      width,
      variant,
      data,
    );

    const visibleIds = useMemo(() => data.map((slice) => slice.id), [data]);

    const donutOverlay = useMemo(
      () =>
        arc()
          .innerRadius(innerRadius)
          .outerRadius(radius)
          .startAngle(0)
          .endAngle(360)({} as DefaultArcObject),
      [innerRadius, radius],
    ) as string | undefined;

    return (
      <div className={container} ref={forwardedRef}>
        {variant === 'donut' && (
          <InnerWrapper
            width={width}
            height={height}
            innerRadius={innerRadius}
            visibleIds={visibleIds}
          />
        )}

        <svg width={width} height={height} style={{ overflow: 'visible' }}>
          <Group
            top={topCenter}
            left={leftCenter}
            onMouseEnter={onMouseEnterHandler}
            onMouseMove={onMouseMoveHandler}
            onMouseLeave={onMouseLeaveHandler}
          >
            {variant === 'pie' ? (
              <circle
                cx="0"
                cy="0"
                r={radius > 0 ? radius : 0}
                fill="transparent"
              />
            ) : (
              <path d={donutOverlay} fill="transparent" />
            )}

            <Pie
              data={data}
              pieValue={getValue}
              outerRadius={radius}
              innerRadius={innerRadius}
              padAngle={0.01}
              pieSort={null}
            >
              {(pie) =>
                pie.arcs.map((arc, index) => (
                  <PieChartSlice
                    key={`slice-${arc.data.id}`}
                    sliceId={`slice-${arc.data.id}`}
                    arc={arc}
                    data={data[index]}
                    path={pie.path}
                  />
                ))
              }
            </Pie>
          </Group>
        </svg>
      </div>
    );
  },
);
